TLM.f("Sancti/06-09",{"officium":"Ss. Primi et Feliciani Martyrum","rule":["Evangelium non appropriatum","vide C3;"],"fallback":"Commune/C3","from":{"Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 44:15; 44:14"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."},{"k":"ref","la":"Ps 32:1"},{"k":"text","la":"Exsultáte, justi, in Dómino: rectos decet collaudátio."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sapiéntiam Sanctórum narrent populi, et laudes eórum núntiet ecclésia: nómina autem eórum vivent in sǽculum sǽculi."}],"Oratio":[{"k":"text","la":"Fac nos, quǽsumus. Dómine, sanctórum Martyrum tuórum Primi et Feliciáni semper festa sectári: quorum suffrágiis protectiónis tuæ dona sentiámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Lectio libri Sapientiæ"},{"k":"ref","la":"Sap 5:16-20"},{"k":"text","la":"Justi autem in perpétuum vivent, et apud Dóminum est merces eórum, et cogitátio illórum apud Altíssimum. Ideo accípient regnum decóris, et diadéma speciéi de manu Dómini: quóniam déxtera sua teget eos, et bráchio sancto suo deféndet illos. Accípiet armatúram zelus illíus, et armábit creatúram ad ultiónem inimicórum. Induet pro thoráce justítiam, et accípiet pro gálea judícium certum. Sumet scutum inexpugnábile æquitátem."}],"Graduale":[{"k":"ref","la":"Ps 88:6; 88:2"},{"k":"text","la":"Confitebúntur cœli mirabília tua, Dómine: etenim veritátem tuam in ecclésia sanctórum."},{"k":"text","la":"Misericórdias tuas, Dómine, in ætérnum cantábo: in generatióne et progénie. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secúta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Hæc est vera fratérnitas, quæ vicit mundi crímina: Christum secúta est, ínclita tenens regna cœléstia. Allelúja.","mark":"V"},{"k":"text","la":"Te Mártyrum candidátus laudat exércitus, Dómine. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 11:25-30"},{"k":"text","la":"In illo témpore: Respóndens Jesus, dixit: Confíteor tibi, Pater, Dómine coeli et terræ, quia abscondísti hæc a sapiéntibus et prudéntibus, et revelásti ea párvulis. Ita, Pater: quóniam sic fuit plácitum ante te. Omnia mihi trádita sunt a Patre meo. Et nemo novit Fílium nisi Pater: neque Patrem quis novit nisi Fílius, et cui volúerit Fílius reveláre. Veníte ad me, omnes, qui laborátis et oneráti estis, et ego refíciam vos. Tóllite jugum meum super vos, et díscite a me, quia mitis sum et húmilis corde: et inveniétis réquiem animábus vestris. Jugum enim meum suáve est et onus meum leve."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Fiat tibi, quǽsumus, Dómine, hóstia sacránda placábilis, pretiósi celebritáte martýrii: quæ et peccáta nostra puríficet, et tuórum tibi vota concíliet famulórum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joannes 15:16"},{"k":"text","la":"Ego vos elégi de mundo, ut eátis et fructum afferátis: et fructus vester máneat."}],"Postcommunio":[{"k":"text","la":"Quǽsumus, omnípotens Deus: ut sanctórum Mártyrum tuórum Primi et Feliciáni cœléstibus mystériis celebráta sollémnitas, indulgéntiam nobis tuæ propitiatiónis acquírat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"b5d434b28ad9400f":{"t":"<i>Pomolimo se</i>.\nDaj da uvijek, molimo, Gospodine, slavimo blagdan svetih mučenika tvojih Prima i Felicijana i da osjećamo po njihovu zatvoru darove tvoje zaštite.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"51d7652276f209e5":{"t":"Bio ti na pomirenje, molimo, Gospodine, dar koji posvećujemo prigodom proslave dragocjenog mučeništva, očistio naše grijehe i preporučio ti želje tvojih slugu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"99aa7a7274814289":{"t":"<i>Pomolimo se</i>.\nMolimo, svemogući Bože, da nam svetkovina svetih mučenika tvojih Prima i Felicijana, proslavljena nebeskim tajnama, pribavi tvoje milosno oproštenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}}});
